//! 📸️ Complete JPEG semantic fields remain in original paid receiving destinations.
use super::{JpgSnapshot,JpgImage,JpgSegment,JfifThumbnail,JfifDensityUnits};
use semio_framework_os_kernel::{io::control::{NativeSnapshotBodyWallet,NativeSnapshotDecodeOwner,NativeSnapshotEncodeOwner},sqlite_snapshot::{SqliteDatabase,SqliteTable,SqliteRow,SqliteValue,SqliteSnapshotControl,SqliteSnapshotReceivingControl,SqliteSnapshotPhase,artifact::receiving::{Port,Direction,Projection,Scalar,row,cell,text_cell,push_row,sort,integer,ordinal,identity_position,parent_range,validate_schema_sql,check_database,settle}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
use std::{cell::{Cell,RefCell},mem::size_of};
pub type Result<T>=std::result::Result<T,ValueError>;
type Paid<'a,'b,'c>=Port<'a,'b,'c,NativeSnapshotBodyWallet>;
const SQL:&str=include_str!("../🗄️.sql");
const TABLES:[(&str,usize);6]=[("jpg_document",9),("jpg_rgba_pixel",7),("jpg_thumbnail",3),("jpg_thumbnail_rgb_pixel",6),("jpg_segment",4),("jpg_segment_octet",4)];
const ORDERED:[usize;4]=[1,3,4,5];
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"JPEG complete semantic state differs")}
fn add(a:usize,b:usize)->Result<usize>{a.checked_add(b).ok_or_else(||ValueError::literal(ValueRefusalKind::WorkLimit,"JPEG semantic extent overflow"))}
fn empty()->JpgSnapshot{JpgSnapshot{schema:String::new(),image:JpgImage::default()}}
#[derive(semio_framework_value::RetireOwned)]
struct Frame{projection:Projection,snapshot:JpgSnapshot,ids:[Vec<usize>;6],ordered:[Vec<usize>;4],status:Option<Result<()>>}
impl Frame{fn new()->Self{Self{projection:Projection::new(),snapshot:empty(),ids:std::array::from_fn(|_|Vec::new()),ordered:std::array::from_fn(|_|Vec::new()),status:None}}}
pub fn definition(index:usize)->&'static str{SQL.split(';').map(str::trim).filter(|sql|!sql.is_empty()).nth(index).unwrap()}
fn table(database:&SqliteDatabase,index:usize)->Result<&SqliteTable>{database.tables.iter().find(|table|table.name.eq_ignore_ascii_case(TABLES[index].0)).ok_or_else(invalid)}
fn text(row:&SqliteRow,column:usize)->Result<&str>{match row.values.get(column){Some(SqliteValue::Text(value))=>Ok(value),_=>Err(invalid())}}
fn bounded(row:&SqliteRow,column:usize,maximum:i64)->Result<i64>{let value=integer(row,column)?;if !(0..=maximum).contains(&value){return Err(invalid())}Ok(value)}
fn id(index:usize)->Result<i64>{ordinal(add(index,1)?)}
fn units(value:JfifDensityUnits)->&'static str{match value{JfifDensityUnits::Aspect=>"aspect",JfifDensityUnits::PixelsPerInch=>"pixelsPerInch",JfifDensityUnits::PixelsPerCm=>"pixelsPerCm"}}
fn equal(source:&str,actual:&str,port:&mut Paid<'_,'_,'_>)->Result<()>{port.work(3,0)?;if source.len()!=actual.len(){return Err(invalid())}let total=source.len();port.control.checkpoint(port.phase(),0,total)?;for(index,(source,actual))in source.as_bytes().chunks(256).zip(actual.as_bytes().chunks(256)).enumerate(){port.work(3,0)?;if source!=actual{return Err(invalid())}port.control.checkpoint(port.phase(),index*256+source.len(),total)?}Ok(())}
fn prefix(output:&mut Projection,table:usize,index:usize,parent:i64,port:&mut Paid<'_,'_,'_>)->Result<()>{row(output,id(index)?,TABLES[table].1,port)?;cell(output,Scalar::Integer(parent),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)}
pub fn pixels(output:&mut Projection,table:usize,bytes:&[u8],channels:usize,port:&mut Paid<'_,'_,'_>)->Result<()>{for(index,pixel)in bytes.chunks(channels).enumerate(){prefix(output,table,index,1,port)?;for channel in 0..channels{cell(output,pixel.get(channel).map(|value|Scalar::Integer(i64::from(*value))).unwrap_or(Scalar::Null),port)?}push_row(output,table,port)?;}Ok(())}
fn project(source:&JpgSnapshot,frame:&mut Frame,port:&mut Paid<'_,'_,'_>)->Result<()>{
 let image=&source.image;let mut octets=0;for segment in &image.other_segments{port.work(1,0)?;octets=add(octets,segment.data.len())?}let counts=[1,image.pixels.len().div_ceil(4),usize::from(image.jfif_thumbnail.is_some()),image.jfif_thumbnail.as_ref().map(|value|value.rgb_data.len().div_ceil(3)).unwrap_or(0),image.other_segments.len(),octets];let total=counts.iter().try_fold(0usize,|sum,count|add(sum,*count))?;port.control.check_rows(total)?;let limits=port.control.limits();let bytes=TABLES.iter().enumerate().try_fold(0usize,|sum,(index,(name,_))|add(sum,add(name.len(),definition(index).len())?))?;if limits.max_tables<6||limits.max_columns<9||bytes>limits.max_schema_bytes||SQL.len()>limits.max_schema_bytes{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"JPEG authored schema exceeds original allowance"))}
 let output=&mut frame.projection;port.vector(6,&mut output.database.tables,1)?;for(index,(name,_))in TABLES.iter().enumerate(){port.work(2,size_of::<SqliteTable>())?;output.database.tables.push(SqliteTable{name:String::new(),sql:String::new(),rows:Vec::new()});let table=&mut output.database.tables[index];port.text(name,&mut table.name,2)?;port.text(definition(index),&mut table.sql,2)?;port.vector(counts[index],&mut table.rows,2)?;}
 row(output,1,9,port)?;text_cell(output,&source.schema,port)?;for value in [i64::from(image.width),i64::from(image.height),i64::from(image.jfif_version.0),i64::from(image.jfif_version.1)]{cell(output,Scalar::Integer(value),port)?}text_cell(output,units(image.jfif_density_units),port)?;cell(output,Scalar::Integer(i64::from(image.jfif_x_density)),port)?;cell(output,Scalar::Integer(i64::from(image.jfif_y_density)),port)?;push_row(output,0,port)?;pixels(output,1,&image.pixels,4,port)?;
 if let Some(thumbnail)=&image.jfif_thumbnail{row(output,1,3,port)?;cell(output,Scalar::Integer(i64::from(thumbnail.width)),port)?;cell(output,Scalar::Integer(i64::from(thumbnail.height)),port)?;push_row(output,2,port)?;pixels(output,3,&thumbnail.rgb_data,3,port)?;}
 let mut current=0;for(index,segment)in image.other_segments.iter().enumerate(){let parent=id(index)?;prefix(output,4,index,1,port)?;cell(output,Scalar::Integer(i64::from(segment.marker)),port)?;push_row(output,4,port)?;for(index,value)in segment.data.iter().enumerate(){row(output,id(current)?,4,port)?;current=add(current,1)?;cell(output,Scalar::Integer(parent),port)?;cell(output,Scalar::Integer(ordinal(index)?),port)?;cell(output,Scalar::Integer(i64::from(*value)),port)?;push_row(output,5,port)?;}}port.control.checkpoint(port.phase(),total,total)
}
fn indexed(database:&SqliteDatabase,frame:&mut Frame,port:&mut Paid<'_,'_,'_>)->Result<()>{
 validate_schema_sql(database,SQL,port)?;check_database(database,port)?;if table(database,0)?.rows.len()!=1||table(database,2)?.rows.len()>1{return Err(invalid())}
 for index in 0..6{let rows=&table(database,index)?.rows;port.vector(rows.len(),&mut frame.ids[index],2)?;for(position,row)in rows.iter().enumerate(){port.work(2,size_of::<usize>())?;if row.values.len()!=TABLES[index].1||integer(row,0)?!=row.rowid||matches!(index,0|2)&&row.rowid!=1{return Err(invalid())}frame.ids[index].push(position);}sort(&mut frame.ids[index],port,|a,b|Ok(rows[a].rowid.cmp(&rows[b].rowid)))?;for pair in frame.ids[index].windows(2){port.work(2,0)?;if rows[pair[0]].rowid==rows[pair[1]].rowid{return Err(invalid())}}}
 for(index,table_index)in ORDERED.into_iter().enumerate(){let rows=&table(database,table_index)?.rows;port.vector(rows.len(),&mut frame.ordered[index],2)?;for position in 0..rows.len(){port.work(2,size_of::<usize>())?;frame.ordered[index].push(position)}sort(&mut frame.ordered[index],port,|a,b|Ok((integer(&rows[a],1)?,integer(&rows[a],2)?).cmp(&(integer(&rows[b],1)?,integer(&rows[b],2)?))))?;let parent=match table_index{3=>2,5=>4,_=>0};for row in rows{if identity_position(&table(database,parent)?.rows,&frame.ids[parent],integer(row,1)?,port)?.is_none(){return Err(invalid())}}}Ok(())
}
fn sequence(database:&SqliteDatabase,frame:&Frame,table_index:usize,order:usize,parent:i64,port:&mut Paid<'_,'_,'_>)->Result<std::ops::Range<usize>>{let rows=&table(database,table_index)?.rows;let range=parent_range(rows,&frame.ordered[order],parent,1,port)?;for(position,index)in frame.ordered[order][range.start..range.end].iter().enumerate(){port.work(2,0)?;if integer(&rows[*index],2)?!=ordinal(position)?{return Err(invalid())}}Ok(range)}
fn read_pixels(rows:&[SqliteRow],ordered:&[usize],channels:usize,source:Option<&[u8]>,output:&mut Vec<u8>,port:&mut Paid<'_,'_,'_>)->Result<()>{
 let mut count=0;for(position,index)in ordered.iter().copied().enumerate(){let row=&rows[index];let mut absent=false;for channel in 0..channels{port.work(3,0)?;if matches!(row.values[3+channel],SqliteValue::Null){if channel==0||position+1!=ordered.len(){return Err(invalid())}absent=true;}else{if absent{return Err(invalid())}bounded(row,3+channel,255)?;count=add(count,1)?;}}}if source.is_some_and(|source|source.len()!=count){return Err(invalid())}if source.is_none(){port.control.admit_reconstruction_bytes(count)?;port.vector(count,output,3)?;}let mut position=0;for index in ordered.iter().copied(){let row=&rows[index];for channel in 0..channels{if matches!(row.values[3+channel],SqliteValue::Null){continue}port.work(3,size_of::<u8>())?;let value=bounded(row,3+channel,255)?as u8;if let Some(source)=source{if source[position]!=value{return Err(invalid())}}else{output.push(value)}position+=1;if position%256==0{port.control.checkpoint(port.phase(),position,count)?;}}}port.control.checkpoint(port.phase(),count,count)
}
fn read(database:&SqliteDatabase,frame:&mut Frame,source:Option<&JpgSnapshot>,port:&mut Paid<'_,'_,'_>)->Result<()>{
 indexed(database,frame,port)?;let document=&table(database,0)?.rows[0];let schema=text(document,1)?;let width=bounded(document,2,i64::from(u32::MAX))?as u32;let height=bounded(document,3,i64::from(u32::MAX))?as u32;let version=(bounded(document,4,255)?as u8,bounded(document,5,255)?as u8);let units=match text(document,6)?{"aspect"=>JfifDensityUnits::Aspect,"pixelsPerInch"=>JfifDensityUnits::PixelsPerInch,"pixelsPerCm"=>JfifDensityUnits::PixelsPerCm,_=>return Err(invalid())};let density=(bounded(document,7,65535)?as u16,bounded(document,8,65535)?as u16);
 if let Some(source)=source{let image=&source.image;if(width,height,version,units,density)!=(image.width,image.height,image.jfif_version,image.jfif_density_units,(image.jfif_x_density,image.jfif_y_density)){return Err(invalid())}equal(&source.schema,schema,port)?;}else{port.control.admit_reconstruction_bytes(schema.len())?;port.text(schema,&mut frame.snapshot.schema,2)?;port.work(2,size_of::<JpgImage>())?;let image=&mut frame.snapshot.image;image.width=width;image.height=height;image.jfif_version=version;image.jfif_density_units=units;image.jfif_x_density=density.0;image.jfif_y_density=density.1;}
 let range=sequence(database,frame,1,0,1,port)?;read_pixels(&table(database,1)?.rows,&frame.ordered[0][range],4,source.map(|source|source.image.pixels.as_slice()),&mut frame.snapshot.image.pixels,port)?;let thumbnail=table(database,2)?.rows.first();if source.is_some_and(|source|source.image.jfif_thumbnail.is_some()!=thumbnail.is_some()){return Err(invalid())}
 if let Some(thumbnail)=thumbnail{let width=bounded(thumbnail,1,255)?as u8;let height=bounded(thumbnail,2,255)?as u8;if let Some(source)=source{let expected=source.image.jfif_thumbnail.as_ref().unwrap();if(width,height)!=(expected.width,expected.height){return Err(invalid())}}else{port.work(2,size_of::<JfifThumbnail>())?;frame.snapshot.image.jfif_thumbnail=Some(JfifThumbnail{width,height,rgb_data:Vec::new()});}let range=sequence(database,frame,3,1,1,port)?;if let Some(source)=source{read_pixels(&table(database,3)?.rows,&frame.ordered[1][range],3,Some(&source.image.jfif_thumbnail.as_ref().unwrap().rgb_data),&mut frame.snapshot.image.pixels,port)?}else{read_pixels(&table(database,3)?.rows,&frame.ordered[1][range],3,None,&mut frame.snapshot.image.jfif_thumbnail.as_mut().unwrap().rgb_data,port)?}}
 let segments=sequence(database,frame,4,2,1,port)?;if source.is_some_and(|source|source.image.other_segments.len()!=segments.len()){return Err(invalid())}if source.is_none(){port.vector(segments.len(),&mut frame.snapshot.image.other_segments,2)?}for(segment_position,index)in segments.enumerate(){let segment=&table(database,4)?.rows[frame.ordered[2][index]];let marker=bounded(segment,3,255)?as u8;let octets=sequence(database,frame,5,3,segment.rowid,port)?;if let Some(source)=source{let expected=&source.image.other_segments[segment_position];if marker!=expected.marker||expected.data.len()!=octets.len(){return Err(invalid())}}else{port.work(2,size_of::<JpgSegment>())?;frame.snapshot.image.other_segments.push(JpgSegment{marker,data:Vec::new()});port.control.admit_reconstruction_bytes(octets.len())?;port.vector(octets.len(),&mut frame.snapshot.image.other_segments.last_mut().unwrap().data,3)?;}for(position,index)in octets.enumerate(){port.work(3,size_of::<u8>())?;let octet=&table(database,5)?.rows[frame.ordered[3][index]];let value=bounded(octet,3,255)?as u8;if let Some(source)=source{if source.image.other_segments[segment_position].data[position]!=value{return Err(invalid())}}else{frame.snapshot.image.other_segments.last_mut().unwrap().data.push(value)}if(position+1)%256==0{port.control.checkpoint(port.phase(),position+1,table(database,5)?.rows.len())?;}}}port.control.checkpoint(port.phase(),1,1)
}
pub struct Settlement<'a,'b>{control:RefCell<SqliteSnapshotReceivingControl<'a,'b>>,before:usize,remaining:usize,phase:SqliteSnapshotPhase,post_body:Cell<bool>,cause:RefCell<Option<ValueError>>}
impl<'a,'b> Settlement<'a,'b>{
 pub fn new(control:&'a mut SqliteSnapshotControl<'b>,before:usize,phase:SqliteSnapshotPhase)->Self{let remaining=control.allocation_remaining_bytes();Self{control:RefCell::new(control.receiving_scope()),before,remaining,phase,post_body:Cell::new(false),cause:RefCell::new(None)}}
 fn settle(&self,owned:usize)->Result<()>{settle(&mut self.control.borrow_mut(),self.remaining,self.before,owned)}
 pub fn finish_body(&self,owned:usize)->Result<()>{self.settle(owned)?;self.post_body.set(true);Ok(())}
 pub fn observe(&self,owned:usize,completed:usize,total:usize)->bool{if !self.post_body.get(){return true}match self.settle(owned).and_then(|_|self.control.borrow_mut().checkpoint(self.phase,completed,total)){Ok(())=>true,Err(error)=>{*self.cause.borrow_mut()=Some(error);false}}}
 fn refused(&self,owned:usize,error:ValueError)->ValueError{match self.settle(owned){Err(cause)=>cause,Ok(())=>self.cause.borrow_mut().take().unwrap_or(error)}}
}
macro_rules! receive{
 ($name:ident,$owner:ident,$progress:path,$direction:ident,$phase:ident,$output:ty,$operation:expr,$publish:expr)=>{
 pub(super)fn $name(source:Option<&JpgSnapshot>,database:Option<&SqliteDatabase>,control:&mut SqliteSnapshotControl<'_>,owner:&mut $owner<'_,'_>)->Result<$output>{
  let result=(||{owner.native().checkpoint()?;let before=owner.native().owned_bytes();let maximum=add(before,control.allocation_remaining_bytes())?;let settlement=Settlement::new(control,before,SqliteSnapshotPhase::$phase);let mut observer=|event:$progress|settlement.observe(event.owned_bytes,event.completed,event.total);let result=owner.scoped_native(maximum,&mut observer,|owner|owner.receive::<Frame,$output>(|slot,native,body|{let mut control=settlement.control.borrow_mut();let mut port=Paid{control:&mut **control,native:Direction::$direction(native),body};port.work(1,size_of::<Frame>())?;*slot=Some(Frame::new());let frame=slot.as_mut().unwrap();port.work(1,size_of::<$output>())?;frame.status=Some(($operation)(source,database,frame,&mut port));let owned=port.owned();drop(port);drop(control);settlement.finish_body(owned)?;frame.status.take().unwrap()?;($publish)(frame)}));match result{Ok(output)=>Ok(output),Err(error)=>Err(settlement.refused(owner.native().owned_bytes(),error))}})();result.map_err(|error|error.with_retained_progress(owner.progress()))
 }
 };
}
